before:
Complete local C++ example; the app itself does not execute it:
```cpp
#include <iostream>
#include <stdexcept>
#include <vector>
void addValidated(std::vector<int>& scores, int score) {
    auto candidate = scores;
    candidate.push_back(score);
    if (score < 0) throw std::invalid_argument("negative");
    scores.swap(candidate);
}
int main() {
    std::vector<int> scores{4};
    try { addValidated(scores, -2); }
    catch (const std::invalid_argument&) { std::cout << "rejected "; }
    std::cout << scores.size() << " " << scores.back() << "\n";
}
```

